// Fixture captured by replaying the original TypeScript Apply against a fixed
// JSON seed. Only generated UUIDs/times and assignment envelope hashes vary.
func coreReplayBind(expected, actual any, ids map[string]string) {
	switch x := expected.(type) {
	case map[string]any:
		y := coreMap(actual)
		if id, ok := x["id"].(string); ok {
			if actualID, ok := y["id"].(string); ok {
				ids[id] = actualID
			}
		}
		for k, v := range x {
			coreReplayBind(v, y[k], ids)
		}
	case []any:
		y := coreList(actual)
		for i, v := range x {
			if i < len(y) {
				coreReplayBind(v, y[i], ids)
			}
		}
	}
}
func coreReplayReplace(v any, ids map[string]string) any {
	switch x := v.(type) {
	case string:
		if id, ok := ids[x]; ok {
			return id
		}
		return x
	case map[string]any:
		r := map[string]any{}
		for k, v := range x {
			r[k] = coreReplayReplace(v, ids)
		}
		return r
	case []any:
		r := []any{}
		for _, v := range x {
			r = append(r, coreReplayReplace(v, ids))
		}
		return r
	}
	return v
}
func coreReplayNormalize(v any, ids map[string]string) any {
	switch x := v.(type) {
	case string:
		if id, ok := ids[x]; ok {
			return id
		}
		return x
	case map[string]any:
		r := map[string]any{}
		for k, v := range x {
			if k == "time" || k == "submittedAt" {
				r[k] = "@timestamp"
			} else if k == "hash" && x["text"] != nil && coreString(v) != coreHash(coreString(x["text"])) {
				r[k] = "@assigned-snapshot:" + coreHash(coreJSON(coreReplayNormalize(x["items"], ids))+coreString(x["text"]))
			} else {
				r[k] = coreReplayNormalize(v, ids)
			}
		}
		return r
	case []any:
		r := []any{}
		for _, v := range x {
			r = append(r, coreReplayNormalize(v, ids))
		}
		return r
	}
	return v
}
func coreReplayDiff(expected, actual any, path string) string {
	if coreJSON(expected) == coreJSON(actual) {
		return ""
	}
	switch x := expected.(type) {
	case map[string]any:
		y, ok := actual.(map[string]any)
		if !ok {
			break
		}
		keys := []string{}
		for k := range x {
			keys = append(keys, k)
		}
		for k := range y {
			if _, ok := x[k]; !ok {
				keys = append(keys, k)
			}
		}
		sort.Strings(keys)
		for _, k := range keys {
			a, aok := x[k]
			b, bok := y[k]
			if aok != bok {
				return path + "." + k + ": field presence differs"
			}
			if d := coreReplayDiff(a, b, path+"."+k); d != "" {
				return d
			}
		}
	case []any:
		y, ok := actual.([]any)
		if !ok {
			break
		}
		if len(x) != len(y) {
			return fmt.Sprintf("%s: lengths expected %d actual %d", path, len(x), len(y))
		}
		for i := range x {
			if d := coreReplayDiff(x[i], y[i], fmt.Sprintf("%s[%d]", path, i)); d != "" {
				return d
			}
		}
	}
	return fmt.Sprintf("%s: expected %s actual %s", path, coreJSON(expected), coreJSON(actual))
}
func TestCoreActionsMatchOriginalTypeScriptReplay(t *testing.T) {
	compressed, e := base64.StdEncoding.DecodeString(coreReplayFixtureGzip)
	if e != nil {
		t.Fatal(e)
	}
	reader, e := gzip.NewReader(bytes.NewReader(compressed))
	if e != nil {
		t.Fatal(e)
	}
	data, e := io.ReadAll(reader)
	reader.Close()
	if e != nil {
		t.Fatal(e)
	}
	var fixture map[string]any
	if e = json.Unmarshal(data, &fixture); e != nil {
		t.Fatal(e)
	}
	state := coreMap(coreClone(fixture["seed"]))
	ids := map[string]string{}
	coreReplayBind(fixture["seed"], state, ids)
	for n, v := range coreList(fixture["steps"]) {
		step := coreMap(v)
		action := coreMap(coreReplayReplace(step["action"], ids))
		candidate := coreMap(coreClone(state))
		var err error
		if action["op"] == "__set" {
			for k, v := range coreMap(action["fields"]) {
				coreFind(coreList(coreMap(coreList(candidate["projects"])[0])["items"]), action["id"])[k] = v
			}
		} else {
			time.Sleep(2 * time.Millisecond)
			err = Apply(candidate, action)
		}
		message := ""
		if err != nil {
			message = err.Error()
		} else {
			state = candidate
		}
		if message != coreString(step["error"]) {
			t.Fatalf("step %d %v: expected error %q actual %q", n+1, action["op"], step["error"], message)
		}
		coreReplayBind(step["state"], state, ids)
		inverse := map[string]string{}
		for expected, actual := range ids {
			inverse[actual] = expected
		}
		expected := coreReplayNormalize(step["state"], nil)
		actual := coreReplayNormalize(state, inverse)
		if difference := coreReplayDiff(expected, actual, "state"); difference != "" {
			t.Fatalf("step %d %v: %s", n+1, action["op"], difference)
		}
	}
}

const coreReplayFixtureGzip = ``
